// An island class whose members are builtin class instances (the shape of
// Next.js's NextRequest.nextUrl.searchParams).
export class RequestLike {
  constructor(url, headers = {}) {
    this.url = new URL(url);
    this.headers = new Headers(headers);
  }
  get searchParams() {
    return this.url.searchParams;
  }
}
export function describeParams(params) {
  return [...params.entries()].map(([k, v]) => `${k}=${v}`).join("&");
}
export function makeParams(query) {
  return new URLSearchParams(query);
}
